							array('question' => '[MIT 6.828 — problème d’examen, en anglais] Suggest a', 'mode' => 'choice', 'xp' => 20, 'hint' => 'Problème d’examen du MIT : rédige ta réponse, puis la correction officielle du MIT s’affiche.', 'explanation' => 'Corrige officiel du MIT : If a file has a link count greater than 1, don\'t embed the inode. Alternative solutions include tracking the entire set of directories where a given file is linked and updating all copies of the inode when any one of them changes, but this would be very slow and poses serious challenges for file system recovery. Simply using symbol links instead of hard links is not a solution, since the semantics of hard links and symbolic links differ significantly.', 'source' => 'MIT OpenCourseWare, 6.828 Operating System Engineering, Fall 2012 — examen et corrigé officiel (MIT EECS)', 'licence' => 'CC BY-NC-SA 4.0', 'choices' => array('Pas to the link problem that achieves the performance beneﬁts of embedded inodes without sacriﬁcing correctness.', 'to the link problem that achieves the performance beneﬁts of embedded inodes without sacriﬁcing correctness.', 'Impossible à déterminer', 'L\'inverse de to the link problem that achieves the performance beneﬁts of embedded inodes without sacriﬁcing correctness.'), 'correct' => 1, 'answer' => 'to the link problem that achieves the performance beneﬁts of embedded inodes without sacriﬁcing correctness.', '_recupere_le' => '2026-11-04T19:55:22.760156+00:00Z', '_strategie' => 'separation_enum_solution'),
